mkdir -p /tmp/w && cat > /tmp/w/load.py <<'EOF'
import json, glob, os, collections, datetime
D='/tmp/export'
R={}
byType=collections.defaultdict(list)
for f in glob.glob(D+'/*.ndjson'):
    t=os.path.basename(f)[:-7]
    for line in open(f):
        r=json.loads(line)
        R[r['id']]=r
        byType[t].append(r)
def ext(r,name):
    for e in r.get('extension',[]):
        if e['url'].endswith('/'+name):
            for k,v in e.items():
                if k.startswith('value'): return v
    return None
def et(r): return ext(r,'event-time')
def subj(r):
    for k in ('subject','patient','for'):
        if k in r and 'reference' in r[k]: return r[k]['reference'].split('/')[-1]
    return None
pats={p['id']:p for p in byType['Patient']}
eps=collections.defaultdict(list)
for e in byType['EpisodeOfCare']: eps[subj(e)].append(e)
charts=collections.defaultdict(list)
for t,rs in byType.items():
    if t in ('Patient','EpisodeOfCare'): continue
    for r in rs:
        s=subj(r)
        if s: charts[s].append(r)
for s in charts: charts[s].sort(key=lambda r:(et(r) or r.get('authoredOn') or ''))
acc_by_num=collections.defaultdict(list)
for b in byType['Basic']:
    acc_by_num[ext(b,'accession')].append(b)
spec_by_acc=collections.defaultdict(list)
for s in byType['Specimen']:
    spec_by_acc[s.get('accessionIdentifier',{}).get('value')].append(s)
EOF
cat > /tmp/w/dump.py <<'EOF'
import sys
sys.path.insert(0,'/tmp/w')
from load import *
pid=sys.argv[1]
p=pats[pid]
print("PATIENT",pid,p['name'][0]['text'],p['birthDate'],p['gender'],"MRN",p['identifier'][0]['value'])
for e in eps[pid]: print("  EPISODE",e['id'],e['period']['start'],e['type'][0]['text'])
for r in charts[pid]:
    t=r['resourceType']; i=r['id']; T=et(r) or r.get('authoredOn')
    if t=='Condition': print(f"{T} {i} Condition: {r['code']['text']} rec={r.get('recorder',{}).get('display')}")
    elif t=='Observation':
        sp=r.get('specimen',{}).get('reference','').split('/')[-1]
        acc=r.get('identifier',[{}])[0].get('value')
        notes='; '.join(n['text'] for n in r.get('note',[]))
        print(f"{T} {i} Obs: {r['code']['text']} coll={r.get('effectiveDateTime')} issued={r.get('issued')} status={r['status']} val={r.get('valueString')!r} acc={acc} spec={sp} note={notes}")
    elif t=='Specimen':
        print(f"{T} {i} Specimen acc={r.get('accessionIdentifier',{}).get('value')} coll={r.get('collection',{}).get('collectedDateTime')} by={r.get('collection',{}).get('collector',{}).get('display')} label={ext(r,'label-name')}/{ext(r,'label-mrn')}/{ext(r,'label-dob')}")
    elif t=='MedicationAdministration':
        print(f"{T} {i} MedAdmin {r['medicationCodeableConcept']['text']} {r.get('dosage',{}).get('text')} status={r['status']} note={'; '.join(n['text'] for n in r.get('note',[]))}")
    elif t=='MedicationDispense':
        print(f"{T} {i} MedDisp {r['medicationCodeableConcept']['text']} qty={r.get('quantity',{}).get('value')} days={r.get('daysSupply',{}).get('value')} instr={[d['text'] for d in r.get('dosageInstruction',[])]} note={'; '.join(n['text'] for n in r.get('note',[]))}")
    elif t=='DocumentReference':
