import json, glob, os, collections, datetime
D='/tmp/export'
R={}
byType=collections.defaultdict(list)
for f in glob.glob(D+'/*.ndjson'):
    t=os.path.basename(f)[:-7]
    for line in open(f):
        r=json.loads(line)
        R[r['id']]=r
        byType[t].append(r)
def ext(r,name):
    for e in r.get('extension',[]):
        if e['url'].endswith('/'+name):
            for k,v in e.items():
                if k.startswith('value'): return v
    return None
def et(r): return ext(r,'event-time')
def subj(r):
    for k in ('subject','patient','for'):
        if k in r and 'reference' in r[k]: return r[k]['reference'].split('/')[-1]
    return None
pats={p['id']:p for p in byType['Patient']}
eps=collections.defaultdict(list)
for e in byType['EpisodeOfCare']: eps[subj(e)].append(e)
charts=collections.defaultdict(list)
for t,rs in byType.items():
    if t in ('Patient','EpisodeOfCare'): continue
    for r in rs:
        s=subj(r)
        if s: charts[s].append(r)
for s in charts: charts[s].sort(key=lambda r:(et(r) or r.get('authoredOn') or ''))
acc_by_num=collections.defaultdict(list)
for b in byType['Basic']:
    acc_by_num[ext(b,'accession')].append(b)
spec_by_acc=collections.defaultdict(list)
for s in byType['Specimen']:
    spec_by_acc[s.get('accessionIdentifier',{}).get('value')].append(s)
